def test_shipping_cost_zero_weight():
    try:
        shipping_cost(0, False)
    except ValueError as e:
        assert str(e) == "weight must be positive"
    else:
        assert False, "Expected ValueError for zero weight"

def test_shipping_cost_negative_weight():
    try:
        shipping_cost(-1, False)
    except ValueError as e:
        assert str(e) == "weight must be positive"
    else:
        assert False, "Expected ValueError for negative weight"
